'domaine-de-chevalier|2015':{blend:{CS:55,ME:35,CF:5,PV:5},harvest:'16 September',alc:13.5,note:'VIGNOBLE ET VINIFICATION Appellation : Pessac-Léognan Sols : graves sur sous-sol argilo-graveleux Vin rouge 55 ha – grand vin 100 000 bouteilles Vin blanc 5 ha – grand vin 18 000 bouteilles BLANC Vendanges : manuelles en cagettes 3 à 5 sélections, au gré de la maturité. au 15 octobre Mise en en bouteille : Juin 2017 2015, ANNÉE SÈCHE ET ENSOLEILLÉE GRANDE QUALITÉ, EN ROUGE ET EN BLANC - Printemps très sec avec une su',src:'2015-Rouge-DOMAINE-de-CHEVALIER-Francais.pdf_.pdf'},
'domaine-de-chevalier|2016':{blend:{CS:55,ME:35,CF:5,PV:5},harvest:'21 octobre',alc:13.5,note:'VIGNOBLE ET VINIFICATION Appellation : Pessac-Léognan Sols : graves sur sous-sol argilo-graveleux Vin rouge 55 ha – grand vin 100 000 bouteilles Vin blanc 6 ha – grand vin 18 000 bouteilles BLANC Vendanges : manuelles en cagettes 3 à 5 sélections, au gré de la maturité. : PESSAC-LEOGNAN VENDANGES (ROUGE) : du 4 au 21 octobre 55 % CABERNET SAUVIGNON – 35 % MERLOT 5% CABERNET FRANC - 5 % PETIT VERDOT Mise en en bouteil',src:'2016-Rouge-DOMAINE-de-CHEVALIER-Francais.pdf_.pdf'},
